import heapq

def stable_toposort(graph):
    # Validate missing dependencies
    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep} (required by {node})")

    # Original insertion order index
    index = {node: i for i, node in enumerate(graph)}

    # Build adjacency: dependency -> dependents
    adjacency = {node: [] for node in graph}
    indegree = {}
    for node, deps in graph.items():
        indegree[node] = len(deps)  # assume no duplicate dependencies
        for dep in deps:
            adjacency[dep].append(node)

    # Min-heap of ready nodes sorted by original index
    heap = []
    for node in graph:
        if indegree[node] == 0:
            heapq.heappush(heap, (index[node], node))

    result = []
    processed = 0

    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        processed += 1

        for dependent in adjacency[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, (index[dependent], dependent))

    if processed != len(graph):
        raise ValueError("Graph contains a cycle")

    return result
