def schema_drift(expected, actual):
    def collect_leaf_paths(schema, prefix):
        paths = []
        for key, value in schema.items():
            new_path = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                paths.extend(collect_leaf_paths(value, new_path))
            else:
                paths.append(new_path)
        return paths

    missing = set()
    extra = set()
    type_diff = set()

    def compare(e, a, path):
        if isinstance(e, dict) and isinstance(a, dict):
            for key in set(e.keys()) | set(a.keys()):
                new_path = f"{path}.{key}" if path else key
                if key in e and key in a:
                    compare(e[key], a[key], new_path)
                elif key in e:
                    if isinstance(e[key], dict):
                        missing.update(collect_leaf_paths(e[key], new_path))
                    else:
                        missing.add(new_path)
                else:
                    if isinstance(a[key], dict):
                        extra.update(collect_leaf_paths(a[key], new_path))
                    else:
                        extra.add(new_path)
        elif isinstance(e, dict) and isinstance(a, str):
            type_diff.add(path if path else "")
            missing.update(collect_leaf_paths(e, path))
        elif isinstance(e, str) and isinstance(a, dict):
            type_diff.add(path if path else "")
            extra.update(collect_leaf_paths(a, path))
        else:  # both leaves
            if e != a:
                type_diff.add(path if path else "")

    compare(expected, actual, "")

    result = set()
    result.update(missing)
    result.update(extra)
    result.update(type_diff)
    return sorted(result)
